<script module lang="ts">
/**
 * Table.Row: a row, a `<tr>`.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { getContext, type Snippet } from 'svelte'

import { chainHandlers, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/table.module.css'

export interface TableRowProps {
  children?: Snippet
  /**
   * Adds hover and a pointer cursor; the row's own primary cell still holds the link.
   */
  interactive?: boolean
  onClick?: () => void
  /**
   * Visual only in a table and semantic in a grid, because `aria-selected` belongs to a `grid`.
   * `undefined` is a third value. Rows that never set `aria-selected` mean the grid has no
   * selection, and `aria-selected="false"` means this row is outside an existing selection.
   * Defaulting to `false` would announce every plain table row as unselected, which tells the
   * reader nothing.
   */
  selected?: boolean
}
</script>

<script lang="ts">
let { children, interactive = false, onClick: onClickOwn, selected }: TableRowProps = $props()
const joined = joinSlot(undefined, () => ({}))
const onClick = $derived(chainHandlers(onClickOwn, joined.passed['onClick']))
const owner: Record<string, any> = getContext('polymorph:Table') ?? {}
const listening = {
  get click() {
    return onClick !== undefined
  },
}
const open = $derived((event: KeyboardEvent) => {
  if (
    event.key !== 'Enter' ||
    !(event.target instanceof HTMLElement) ||
    !event.target.matches('th, td')
  )
    return
  event.preventDefault()
  onClick?.()
})
</script>

{@render joined.start?.()
}{#if joined.shown
  }<tr
    class={styles.row}
    data-interactive={(interactive) ? '' : undefined}
    data-selected={(selected) ? '' : undefined}
    aria-selected={owner.grid && selected !== undefined ? selected : undefined}
    onclick={() => { if (interactive) onClick?.() }}
    onkeydown={(event) => { if (owner.grid && interactive && listening.click) open(event) }}
    >{@render children?.()
  }</tr
>{/if
}{@render joined.end?.()}
